window.AUTH=window.AUTH||{};window.AUTH["20-1263"]={"d":"20-1263","id":"2021/20-1263","n":"Gallardo v. Marstiller","briefs":[{"k":"petitioner","label":"Brief of petitioner Gianinna Gallardo","date":"2021-09-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1263/192535/20210915155722541_Merits%20Brief.pdf","side":"pet","n":66},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2021-09-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-1263/193471/20210922191708053_20-1263tsacUnitedStates.pdf","side":"us","n":38},{"k":"respondent","label":"Brief of respondent Simone Marstiller","date":"2021-11-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1263/199951/20211115152236251_Final%20brief%20to%20printer%20revised%20after%20proof.pdf","side":"res","n":47},{"k":"reply","label":"Reply of petitioner Gianinna Gallardo","date":"2021-12-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1263/205225/20211215145219680_Gallardo%20-%20Reply%20Brief.pdf","side":"pet","n":9}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us1r34_c9dh.pdf","tr":true,"items":[{"t":"case","label":"Ark. Dep’t of Health & Human Servs. v. Ahlborn","cite":"547 U.S. 268","y":2006,"id":"2005/04-1506","sc":1,"op":13,"sum":"The Court ruled that federal Medicaid statutes only allow a state to recover the part of a third-party settlement earmarked for medical expenses. The Justices agreed with the Circuit Court that the statutes do not permit Arkansas to require Ahlborn to repay Medicare expenses from the non-medical portions of the settlement.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"0":"36","3":"21"}},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"137 S. Ct. 1190","y":2017,"id":"2016/16-149","sc":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"0":"42","2":"42"}},{"t":"case","label":"D. Ginsberg & Sons v. Popkin","cite":"285 U.S. 204","y":1932,"id":"scdb/1931-109","sc":1,"sum":"A court of bankruptcy has no authority under § 2 (15) of the Bankruptcy Act or § 261 of the Judicial Code to issue a writ of ne exeat against an absconding officer of a bankrupt corporation to the end that he may be examined in the bankruptcy proceedings. P. 206. 50 F. (2d) 693, affirmed. CERTIORARI, 284 U. S. 609, to review the reversal of an order sustaining the issuance of a writ of ne exeat in bankruptcy …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Doe v. Vt. Off. of Health Access","cite":"54 A.3d 474","y":2012,"court":"Vt.","url":"https://www.courtlistener.com/c/A.3d/54/474/","op":1,"by":{"0":"28","1":"10"}},{"t":"case","label":"Doleman v. Levine","cite":"295 U.S. 221","y":1935,"id":"scdb/1934-057","sc":1,"sum":"Under the Longshoremen's & Harbor Workers' Compensation Act, made applicable to the District 6f Columbia as a compensation law, where several persons, as dependants or next of kin, aie entitled to claim compensation under the Act, or damages under the District of Columbia death statute, on account of the death of an employee caused by the negligence of a stranger to the employment, an election by one of them to take …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43, 44"}},{"t":"case","label":"E.M.A. ex rel. Plyler v. Cansler","cite":"674 F.3d 290","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/674/290/","by":{"0":"10, 11"}},{"t":"case","label":"Eady v. State","cite":"279 So. 3d 1249","y":2019,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%203d/279/1249/","by":{"0":"15"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2019,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Giraldo v. Agency for Health Care Admin.","cite":"248 So. 3d 53","y":2018,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%203d/248/53/","op":2,"by":{"0":"20","2":"9"}},{"t":"case","label":"Hedgebeth v. Medford","cite":"378 A.2d 226","y":1977,"court":"N.J.","url":"https://www.courtlistener.com/c/A.2d/378/226/","by":{"0":"48"}},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"sum":"The Court found that the Federal Employees' Group Life Insurance Act preempts a Virginia state law regarding beneficiary designation upon divorce.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Kahrs v. Sanchez","cite":"956 P.2d 132","y":1997,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/956/132/","sum":"Holding the addition of assignment rights authorized by § 1396k “did not mandate a greater return to the State than the amount available by subrogation”.","sumSrc":"brief:0","by":{"0":"45, 48, 49"}},{"t":"case","label":"Latham v. Off. of Recovery Servs.","cite":"448 P.3d 1241","y":2019,"court":"Utah","url":"https://www.courtlistener.com/c/P.3d/448/1241/","op":1,"by":{"0":"33, 35"}},{"t":"case","label":"Medtronic v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Montanile v. Bd. of Trustees of Nat’l Elevator Indus. Health Ben. Plan","cite":"577 U.S. 136","y":2016,"id":"2015/14-723","sc":1,"sum":"The Court determined that the Employee Retirement Income Security Act of 1974 does not allow for a suit to recover reimbursement of an asset that has been fully disbursed on non-traceable items such as services.","sumSrc":"Oyez","by":{"0":"42, 46"}},{"t":"case","label":"Off. of Recovery Servs. v. Latham","cite":"140 S. Ct. 852","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/852/","sc":1,"by":{"0":"47"}},{"t":"case","label":"Panama Ref. Co. v. Ryan","cite":"293 U.S. 388","y":1935,"id":"1900-1940/293us388","sc":1,"op":1,"sum":"Writing for the 8-1 majority, Chief Justice Charles E. Hughes concluded the order was not constitutional. Supreme Court held that in enacting the order, the President subsumed legislative powers that Congress does not have the power to delegate. Congress cannot delegate legislative powers to other branches of government in order to sustain the democratic system of government.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"S.W. Fiduciary v. Ariz. Health Care Cost Containment Sys. Admin.","cite":"249 P.3d 1104","y":2011,"court":"Ariz. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/249/1104/","by":{"0":"28","2":"44"}},{"t":"case","label":"Sereboff v. Mid Atlantic Med. Servs., Inc.","cite":"547 U.S. 356","y":2006,"id":"2005/05-260","sc":1,"op":10,"sum":"In Barnes, an attorney's promise to pay two other attorneys a portion of the money he collected from a case that had yet to be decided was held legally binding. Roberts wrote that equity had once required a contract to specify an existing fund from which money would be paid (which could not have happened in this case), but that after Barnes this was no longer the case.","sumSrc":"Oyez","by":{"0":"42, 43"}},{"t":"case","label":"Smith v. Ala. Medicaid Agency","cite":"461 So. 2d 817","y":1984,"court":"Ala. Civ. App.","url":"https://www.courtlistener.com/c/So.%202d/461/817/","by":{"0":"45"}},{"t":"case","label":"State v. Cowdell","cite":"421 N.E.2d 667","y":1981,"court":"Ind. Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/421/667/","by":{"0":"45"}},{"t":"case","label":"Underwood v. Dep’t of Health & Rehab. Servs.","cite":"551 So. 2d 522","y":1989,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/551/522/","by":{"0":"40, 42, 46"}},{"t":"case","label":"United States v. Aetna Cas. & Surety Co.","cite":"338 U.S. 366","y":1949,"id":"scdb/1949-019","sc":1,"sum":"Notwithstanding R. S. § 3477, restricting assignments of claims against the United States, an insurance company may bring an action under the Federal Tort Claims Act in its own name against the United States upon a claim to which it has become subrogated by payment to an insured who would have been able to bring such action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 44"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"ar":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Vt. Agency of Nat. Resources v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"W. Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 33"}},{"t":"case","label":"White v. Sutherland","cite":"585 P.2d 331","y":1978,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/585/331/","by":{"0":"45, 48"}},{"t":"case","label":"Wos v. E.M.A. ex rel. Johnson","cite":"568 U.S. 627","y":2013,"id":"2012/12-98","sc":1,"op":3,"sum":"The Court held that federal law preempts North Carolina's state law regarding reimbursement of medical expenses from a patient's settlement.","sumSrc":"Oyez","by":{"0":"passim","1":"4, 5, 23, 29, 30","2":"passim","3":"11, 19, 21"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1167","url":"https://www.law.cornell.edu/uscode/text/29/1167","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","stext":{"head":"§1396. Medicaid and CHIP Payment and Access Commission","paras":[[0,"(a) Establishment"],[0,"There is hereby established the Medicaid and CHIP Payment and Access Commission (in this section referred to as \"MACPAC\")."],[0,"(b) Duties"],[0,"(1) Review of access policies for all States and annual reports"],[1,"MACPAC shall—"],[2,"(A) review policies of the Medicaid program established under this subchapter (in this section referred to as \"Medicaid\") and the State Children's Health Insurance Program established under subchapter XXI (in this section referred to as \"CHIP\") affecting access to covered items and services, including topics described in paragraph (2);"],[2,"(B) make recommendations to Congress, the Secretary, and States concerning such access policies;"],[2,"(C) by not later than March 15 of each year (beginning with 2010), submit a report to Congress containing the results of such reviews and MACPAC's recommendations concerning such policies; and"],[2,"(D) by not later than June 15 of each year (beginning with 2010), submit a report to Congress containing an examination of issues affecting Medicaid and CHIP, including the implications of changes in health care delivery in the United States and in the market for health care services on such programs."],[0,"(2) Specific topics to be reviewed"],[1,"Specifically, MACPAC shall review and assess the following:"],[0,"(A) Medicaid and CHIP payment policies"],[2,"Payment policies under Medicaid and CHIP, including—"],[3,"(i) the factors affecting expenditures for the efficient provision of items and services in different sectors, including the process for updating payments to medical, dental, and health professionals, hospitals, residential and long-term care providers, providers of home and community based services, Federally-qualified health centers and rural health clinics, managed care entities, and providers of other covered items and services;"],[3,"(ii) payment methodologies; and"],[3,"(iii) the relationship of such factors and methodologies to access and quality of care for Medicaid and CHIP beneficiaries (including how such factors and methodologies enable such beneficiaries to obtain the services for which they are eligible, affect provider supply, and affect providers that serve a disproportionate share of low-income and other vulnerable populations)."],[0,"(B) Eligibility policies"],[2,"Medicaid and CHIP eligibility policies, including a determination of the degree to which Federal and State policies provide health care coverage to needy populations."],[0,"(C) Enrollment and retention processes"],[2,"Medicaid and CHIP enrollment and retention processes, including a determination of the degree to which Federal and State policies encourage the enrollment of individuals who are eligible for such programs and screen out individuals who are ineligible, while minimizing the share of program expenses devoted to such processes."],[0,"(D) Coverage policies"],[2,"Medicaid and CHIP benefit and coverage policies, including a determination of the degree to which Federal and State policies provide access to the services enrollees require to improve and maintain their health and functional status."],[0,"(E) Quality of care"],[2,"Medicaid and CHIP policies as they relate to the quality of care provided under those programs, including a determination of the degree to which Federal and State policies achieve their stated goals and interact with similar goals established by other purchasers of health care services."],[0,"(F) Interaction of Medicaid and CHIP payment policies with health care delivery generally"],[2,"The effect of Medicaid and CHIP payment policies on access to items and services for children and other Medicaid and CHIP populations other than under this subchapter or subchapter XXI and the implications of changes in health care delivery in the United States and in the general market for health care items and services on Medicaid and CHIP."],[0,"(G) Interactions with Medicare and Medicaid"],[2,"Consistent with paragraph (11), the interaction of policies under Medicaid and the Medicare program under subchapter XVIII, including with respect to how such interactions affect access to services, payments, and dual eligible individuals."],[0,"(H) Other access policies"],[2,"The effect of other Medicaid and CHIP policies on access to covered items and services, including policies relating to transportation and language barriers and preventive, acute, and long-term services and supports."],[0,"(3) Recommendations and reports of State-specific data"],[1,"MACPAC shall—"],[2,"(A) review national and State-specific Medicaid and CHIP data; and"],[2,"(B) submit reports and recommendations to Congress, the Secretary, and States based on such reviews."],[0,"(4) Creation of early-warning system"],[1,"MACPAC shall create an early-warning system to identify provider shortage areas, as well as other factors that adversely affect, or have the potential to adversely affect, access to care by, or the health care status of, Medicaid and CHIP beneficiaries. MACPAC shall include in the annual report required under paragraph (1)(D) a description of all such areas or problems identified with respect to the period addressed in the report."],[0,"(5) Comments on certain secretarial reports and regulations"],[0,"(A) Certain secretarial reports"],[2,"If the Secretary submits to Congress (or a committee of Congress) a report that is required by law and that relates to access policies, including with respect to payment policies, under Medicaid or CHIP, the Secretary shall transmit a copy of the report to MACPAC. MACPAC shall review the report and, not later than 6 months after the date of submittal of the Secretary's report to Congress, shall submit to the appropriate committees of Congress and the Secretary written comments on such report. Such comments may include such recommendations as MACPAC deems appropriate."],[0,"(B) Regulations"],[2,"MACPAC shall review Medicaid and CHIP regulations and may comment through submission of a report to the appropriate committees of Congress and the Secretary, on any such regulations that affect access, quality, or efficiency of health care."],[0,"(6) Agenda and additional reviews"],[0,"(A) In general"],[2,"MACPAC shall consult periodically with the chairmen and ranking minority members of the appropriate committees of Congress regarding MACPAC's agenda and progress towards achieving the agenda. MACPAC may conduct additional reviews, and submit additional reports to the appropriate committees of Congress, from time to time on such topics relating to the program under this subchapter or subchapter XXI as may be requested by such chairmen and members and as MACPAC deems appropriate."],[0,"(B) Review and reports regarding Medicaid DSH"],[0,"(i) In general"],[3,"MACPAC shall review and submit an annual report to Congress on disproportionate share hospital payments under section 1396r–4 of this title. Each report shall include the information specified in clause (ii)."],[0,"(ii) Required report information"],[3,"Each report required under this subparagraph shall include the following:"],[4,"(I) Data relating to changes in the number of uninsured individuals."],[4,"(II) Data relating to the amount and sources of hospitals' uncompensated care costs, including the amount of such costs that are the result of providing unreimbursed or under-reimbursed services, charity care, or bad debt."],[4,"(III) Data identifying hospitals with high levels of uncompensated care that also provide access to essential community services for low-income, uninsured, and vulnerable populations, such as graduate medical education, and the continuum of primary through quarternary care, including the provision of trauma care and public health services."],[4,"(IV) State-specific analyses regarding the relationship between the most recent State DSH allotment and the projected State DSH allotment for the succeeding year and the data reported under subclauses (I), (II), and (III) for the State."],[0,"(iii) Data"],[3,"Notwithstanding any other provision of law, the Secretary regularly shall provide MACPAC with the most recent State reports and most recent independent certified audits submitted under section 1396r–4(j) of this title, cost reports submitted under subchapter XVIII, and such other data as MACPAC may request for purposes of conducting the reviews and preparing and submitting the annual reports required under this subparagraph."],[0,"(iv) Submission deadlines"],[3,"The first report required under this subparagraph shall be submitted to Congress not later than February 1, 2016. Subsequent reports shall be submitted as part of, or with, each annual report required under paragraph (1)(C) during the period of fiscal years 2017 through 2024."],[0,"(7) Availability of reports"],[1,"MACPAC shall transmit to the Secretary a copy of each report submitted under this subsection and shall make such reports available to the public."],[0,"(8) Appropriate committee of Congress"],[1,"For purposes of this section, the term \"appropriate committees of Congress\" means the Committee on Energy and Commerce of the House of Representatives and the Committee on Finance of the Senate."],[0,"(9) Voting and reporting requirements"],[1,"With respect to each recommendation contained in a report submitted under paragraph (1), each member of MACPAC shall vote on the recommendation, and MACPAC shall include, by member, the results of that vote in the report containing the recommendation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396?type=usc&year=mostrecent&link-type=html"},"head":"§1396. Medicaid and CHIP Payment and Access Commission","tname":"The Public Health and Welfare","by":{"0":"2","1":"2"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","subs":["(a)","(a)(18)","(a)(25)(A)","(a)(25)(B)","(a)(25)(H)","(l)(1)(A)","(a)(25)(I)","(a)(25)(I)(ii)"],"stext":{"head":"§1396a. State plans for medical assistance","paras":[[0,"(a) Contents"],[0,"A State plan for medical assistance must—"],[1,"(1) provide that it shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(2) provide for financial participation by the State equal to not less than 40 per centum of the non-Federal share of the expenditures under the plan with respect to which payments under section 1396b of this title are authorized by this subchapter; and, effective July 1, 1969, provide for financial participation by the State equal to all of such non-Federal share or provide for distribution of funds from Federal or State sources, for carrying out the State plan, on an equalization or other basis which will assure that the lack of adequate funds from local sources will not result in lowering the amount, duration, scope, or quality of care and services available under the plan;"],[1,"(3) provide for granting an opportunity for a fair hearing before the State agency to any individual whose claim for medical assistance under the plan is denied or is not acted upon with reasonable promptness;"],[1,"(4) provide (A) such methods of administration (including methods relating to the establishment and maintenance of personnel standards on a merit basis, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, and compensation of any individual employed in accordance with such methods, including provision for utilization of professional medical personnel in the administration and, where administered locally, supervision of administration of the plan, and, subject to section 1396b(i) of this title, including a specification that the single State agency described in paragraph (5) will ensure necessary transportation for beneficiaries under the State plan to and from providers and a description of the methods that such agency will use to ensure such transportation) as are found by the Secretary to be necessary for the proper and efficient operation of the plan, (B) for the training and effective use of paid subprofessional staff, with particular emphasis on the full-time or part-time employment of recipients and other persons of low income, as community service aides, in the administration of the plan and for the use of nonpaid or partially paid volunteers in a social service volunteer program in providing services to applicants and recipients and in assisting any advisory committees established by the State agency, (C) that each State or local officer, employee, or independent contractor who is responsible for the expenditure of substantial amounts of funds under the State plan, each individual who formerly was such an officer, employee, or contractor, and each partner of such an officer, employee, or contractor shall be prohibited from committing any act, in relation to any activity under the plan, the commission of which, in connection with any activity concerning the United States Government, by an officer or employee of the United States Government, an individual who was such an officer or employee, or a partner of such an officer or employee is prohibited by section 207 or 208 of title 18, and (D) that each State or local officer, employee, or independent contractor who is responsible for selecting, awarding, or otherwise obtaining items and services under the State plan shall be subject to safeguards against conflicts of interest that are at least as stringent as the safeguards that apply under chapter 21 of title 41 to persons described in section 2102(a)(3) of title 41;"],[1,"(5) either provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan; or provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan, except that the determination of eligibility for medical assistance under the plan shall be made by the State or local agency administering the State plan approved under subchapter I or XVI (insofar as it relates to the aged) if the State is eligible to participate in the State plan program established under subchapter XVI, or by the agency or agencies administering the supplemental security income program established under subchapter XVI or the State plan approved under part A of subchapter IV if the State is not eligible to participate in the State plan program established under subchapter XVI;"],[1,"(6) provide that the State agency will make such reports, in such form and containing such information, as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provide—"],[2,"(A) safeguards which restrict the use or disclosure of information concerning applicants and recipients to purposes directly connected with—"],[3,"(i) the administration of the plan; and"],[3,"(ii) the exchange of information necessary to certify or verify the certification of eligibility of children for free or reduced price breakfasts under the Child Nutrition Act of 1966 [42 U.S.C. 1771 et seq.] and free or reduced price lunches under the Richard B. Russell National School Lunch Act [42 U.S.C. 1751 et seq.], in accordance with section 9(b) of that Act [42 U.S.C. 1758(b)], using data standards and formats established by the State agency; and"],[2,"(B) that, notwithstanding the Express Lane option under subsection (e)(13), the State may enter into an agreement with the State agency administering the school lunch program established under the Richard B. Russell National School Lunch Act under which the State shall establish procedures to ensure that—"],[3,"(i) a child receiving medical assistance under the State plan under this subchapter whose family income does not exceed 133 percent of the poverty line (as defined in section 9902(2) of this title, including any revision required by such section), as determined without regard to any expense, block, or other income disregard, applicable to a family of the size involved, may be certified as eligible for free lunches under the Richard B. Russell National School Lunch Act and free breakfasts under the Child Nutrition Act of 1966 without further application; and"],[3,"(ii) the State agencies responsible for administering the State plan under this subchapter, and for carrying out the school lunch program established under the Richard B. Russell National School Lunch Act (42 U.S.C. 1751 et seq.) or the school breakfast program established by section 4 of the Child Nutrition Act of 1966 (42 U.S.C. 1773), cooperate in carrying out paragraphs (3)(F) and (15) of section 9(b) of that Act [42 U.S.C. 1758(b)];"],[1,"(8) provide that all individuals wishing to make application for medical assistance under the plan shall have opportunity to do so, and that such assistance shall be furnished with reasonable promptness to all eligible individuals;"],[1,"(9) provide—"],[2,"(A) that the State health agency, or other appropriate State medical agency (whichever is utilized by the Secretary for the purpose specified in the first sentence of section 1395aa(a) of this title), shall be responsible for establishing and maintaining health standards for private or public institutions in which recipients of medical assistance under the plan may receive care or services,"],[2,"(B) for the establishment or designation of a State authority or authorities which shall be responsible for establishing and maintaining standards, other than those relating to health, for such institutions,"],[2,"(C) that any laboratory services paid for under such plan must be provided by a laboratory which meets the applicable requirements of section 1395x(e)(9) of this title or paragraphs (16) and (17) of section 1395x(s) of this title, or, in the case of a laboratory which is in a rural health clinic, of section 1395x(aa)(2)(G) of this title, and"],[2,"(D) that the State maintain a consumer-oriented website providing useful information to consumers regarding all skilled nursing facilities and all nursing facilities in the State, including for each facility, Form 2567 State inspection reports (or a successor form), complaint investigation reports, the facility's plan of correction, and such other information that the State or the Secretary considers useful in assisting the public to assess the quality of long term care options and the quality of care provided by individual facilities;"],[1,"(10) provide—"],[2,"(A) for making medical assistance available, including at least the care and services listed in paragraphs (1) through (5), (13)(B), (17), (21), (28), (29), and (30) of section 1396d(a) of this title, to—"],[3,"(i) all individuals—"],[4,"(I) who are receiving aid or assistance under any plan of the State approved under subchapter I, X, XIV, or XVI, or part A or part E of subchapter IV (including individuals eligible under this subchapter by reason of section 602(a)(37),1 606(h),1 or 673(b) of this title, or considered by the State to be receiving such aid as authorized under section 682(e)(6)1 of this title),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396a?type=usc&year=mostrecent&link-type=html"},"head":"§1396a. State plans for medical assistance","tname":"The Public Health and Welfare","by":{"0":"i, 3, 4, 3, 4, 5, 3, 4, 5, 1, 3, 4, 6, 4","1":"26, 2, 8, 11, 12, 13, 2, 8, 14, 20, 2, 13, 14, 20, passim, 20, 18"}},{"t":"usc","label":"42 U.S.C. § 1396k","url":"https://www.law.cornell.edu/uscode/text/42/1396k","subs":["(a)","(a)(1)(A)","(a)(1)(C)","(b)"],"stext":{"head":"§1396k. Assignment, enforcement, and collection of rights of payments for medical care; establishment of procedures pursuant to State plan; amounts retained by State","paras":[[0,"(a) For the purpose of assisting in the collection of medical support payments and other payments for medical care owed to recipients of medical assistance under the State plan approved under this subchapter, a State plan for medical assistance shall—"],[1,"(1) provide that, as a condition of eligibility for medical assistance under the State plan to an individual who has the legal capacity to execute an assignment for himself, the individual is required—"],[2,"(A) to assign the State any rights, of the individual or of any other person who is eligible for medical assistance under this subchapter and on whose behalf the individual has the legal authority to execute an assignment of such rights, to support (specified as support for the purpose of medical care by a court or administrative order) and to payment for medical care from any third party;"],[2,"(B) to cooperate with the State (i) in establishing the paternity of such person (referred to in subparagraph (A)) if the person is a child born out of wedlock, and (ii) in obtaining support and payments (described in subparagraph (A)) for himself and for such person, unless (in either case) the individual is described in section 1396a(l)(1)(A) of this title or the individual is found to have good cause for refusing to cooperate as determined by the State agency in accordance with standards prescribed by the Secretary, which standards shall take into consideration the best interests of the individuals involved; and"],[2,"(C) to cooperate with the State in identifying, and providing information to assist the State in pursuing, any third party who may be liable to pay for care and services available under the plan, unless such individual has good cause for refusing to cooperate as determined by the State agency in accordance with standards prescribed by the Secretary, which standards shall take into consideration the best interests of the individuals involved; and"],[1,"(2) provide for entering into cooperative arrangements (including financial arrangements), with any appropriate agency of any State (including, with respect to the enforcement and collection of rights of payment for medical care by or through a parent, with a State's agency established or designated under section 654(3) of this title) and with appropriate courts and law enforcement officials, to assist the agency or agencies administering the State plan with respect to (A) the enforcement and collection of rights to support or payment assigned under this section and (B) any other matters of common concern."],[0,"(b) Such part of any amount collected by the State under an assignment made under the provisions of this section shall be retained by the State as is necessary to reimburse it for medical assistance payments made on behalf of an individual with respect to whom such assignment was executed (with appropriate reimbursement of the Federal Government to the extent of its participation in the financing of such medical assistance), and the remainder of such amount collected shall be paid to such individual."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396k?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":2,"head":"§1396k. Assignment, enforcement, and collection of rights of payments for medical care; establishment of procedures pursuant to State plan; amounts retained by State","tname":"The Public Health and Welfare","by":{"0":"i, 4, 5, 5, 4, 5","1":"passim, 17, 18, 28, 3, 4, 16, 21, 17, 20, 29"}},{"t":"usc","label":"42 U.S.C. § 1396p","url":"https://www.law.cornell.edu/uscode/text/42/1396p","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(1)(B)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(b)(1)(C)"],"stext":{"head":"§1396p. Liens, adjustments and recoveries, and transfers of assets","paras":[[0,"(a) Imposition of lien against property of an individual on account of medical assistance rendered to him under a State plan"],[0,"(1) No lien may be imposed against the property of any individual prior to his death on account of medical assistance paid or to be paid on his behalf under the State plan, except—"],[1,"(A) pursuant to the judgment of a court on account of benefits incorrectly paid on behalf of such individual, or"],[1,"(B) in the case of the real property of an individual—"],[2,"(i) who is an inpatient in a nursing facility, intermediate care facility for the mentally retarded, or other medical institution, if such individual is required, as a condition of receiving services in such institution under the State plan, to spend for costs of medical care all but a minimal amount of his income required for personal needs, and"],[2,"(ii) with respect to whom the State determines, after notice and opportunity for a hearing (in accordance with procedures established by the State), that he cannot reasonably be expected to be discharged from the medical institution and to return home,"],[1,"except as provided in paragraph (2)."],[0,"(2) No lien may be imposed under paragraph (1)(B) on such individual's home if—"],[1,"(A) the spouse of such individual,"],[1,"(B) such individual's child who is under age 21, or (with respect to States eligible to participate in the State program established under subchapter XVI) is blind or permanently and totally disabled, or (with respect to States which are not eligible to participate in such program) is blind or disabled as defined in section 1382c of this title, or"],[1,"(C) a sibling of such individual (who has an equity interest in such home and who was residing in such individual's home for a period of at least one year immediately before the date of the individual's admission to the medical institution),"],[0,"is lawfully residing in such home."],[0,"(3) Any lien imposed with respect to an individual pursuant to paragraph (1)(B) shall dissolve upon that individual's discharge from the medical institution and return home."],[0,"(b) Adjustment or recovery of medical assistance correctly paid under a State plan"],[0,"(1) No adjustment or recovery of any medical assistance correctly paid on behalf of an individual under the State plan may be made, except that the State shall seek adjustment or recovery of any medical assistance correctly paid on behalf of an individual under the State plan in the case of the following individuals:"],[1,"(A) In the case of an individual described in subsection (a)(1)(B), the State shall seek adjustment or recovery from the individual's estate or upon sale of the property subject to a lien imposed on account of medical assistance paid on behalf of the individual."],[1,"(B) In the case of an individual who was 55 years of age or older when the individual received such medical assistance, the State shall seek adjustment or recovery from the individual's estate, but only for medical assistance consisting of—"],[2,"(i) nursing facility services, home and community-based services, and related hospital and prescription drug services, or"],[2,"(ii) at the option of the State, any items or services under the State plan (but not including medical assistance for medicare cost-sharing or for benefits described in section 1396a(a)(10)(E) of this title)."],[1,"(C)(i) In the case of an individual who has received (or is entitled to receive) benefits under a long-term care insurance policy in connection with which assets or resources are disregarded in the manner described in clause (ii), except as provided in such clause, the State shall seek adjustment or recovery from the individual's estate on account of medical assistance paid on behalf of the individual for nursing facility and other long-term care services."],[1,"(ii) Clause (i) shall not apply in the case of an individual who received medical assistance under a State plan of a State which had a State plan amendment approved as of May 14, 1993, and which satisfies clause (iv), or which has a State plan amendment that provides for a qualified State long-term care insurance partnership (as defined in clause (iii)) which provided for the disregard of any assets or resources—"],[2,"(I) to the extent that payments are made under a long-term care insurance policy; or"],[2,"(II) because an individual has received (or is entitled to receive) benefits under a long-term care insurance policy."],[1,"(iii) For purposes of this paragraph, the term \"qualified State long-term care insurance partnership\" means an approved State plan amendment under this subchapter that provides for the disregard of any assets or resources in an amount equal to the insurance benefit payments that are made to or on behalf of an individual who is a beneficiary under a long-term care insurance policy if the following requirements are met:"],[2,"(I) The policy covers an insured who was a resident of such State when coverage first became effective under the policy."],[2,"(II) The policy is a qualified long-term care insurance policy (as defined in section 7702B(b) of the Internal Revenue Code of 1986) issued not earlier than the effective date of the State plan amendment."],[2,"(III) The policy meets the model regulations and the requirements of the model Act specified in paragraph (5)."],[2,"(IV) If the policy is sold to an individual who—"],[3,"(aa) has not attained age 61 as of the date of purchase, the policy provides compound annual inflation protection;"],[3,"(bb) has attained age 61 but has not attained age 76 as of such date, the policy provides some level of inflation protection; and"],[3,"(cc) has attained age 76 as of such date, the policy may (but is not required to) provide some level of inflation protection."],[2,"(V) The State Medicaid agency under section 1396a(a)(5) of this title provides information and technical assistance to the State insurance department on the insurance department's role of assuring that any individual who sells a long-term care insurance policy under the partnership receives training and demonstrates evidence of an understanding of such policies and how they relate to other public and private coverage of long-term care."],[2,"(VI) The issuer of the policy provides regular reports to the Secretary, in accordance with regulations of the Secretary, that include notification regarding when benefits provided under the policy have been paid and the amount of such benefits paid, notification regarding when the policy otherwise terminates, and such other information as the Secretary determines may be appropriate to the administration of such partnerships."],[2,"(VII) The State does not impose any requirement affecting the terms or benefits of such a policy unless the State imposes such requirement on long-term care insurance policies without regard to whether the policy is covered under the partnership or is offered in connection with such a partnership."],[1,"In the case of a long-term care insurance policy which is exchanged for another such policy, subclause (I) shall be applied based on the coverage of the first such policy that was exchanged. For purposes of this clause and paragraph (5), the term \"long-term care insurance policy\" includes a certificate issued under a group insurance contract."],[1,"(iv) With respect to a State which had a State plan amendment approved as of May 14, 1993, such a State satisfies this clause for purposes of clause (ii) if the Secretary determines that the State plan amendment provides for consumer protection standards which are no less stringent than the consumer protection standards which applied under such State plan amendment as of December 31, 2005."],[1,"(v) The regulations of the Secretary required under clause (iii)(VI) shall be promulgated after consultation with the National Association of Insurance Commissioners, issuers of long-term care insurance policies, States with experience with long-term care insurance partnership plans, other States, and representatives of consumers of long-term care insurance policies, and shall specify the type and format of the data and information to be reported and the frequency with which such reports are to be made. The Secretary, as appropriate, shall provide copies of the reports provided in accordance with that clause to the State involved."],[1,"(vi) The Secretary, in consultation with other appropriate Federal agencies, issuers of long-term care insurance, the National Association of Insurance Commissioners, State insurance commissioners, States with experience with long-term care insurance partnership plans, other States, and representatives of consumers of long-term care insurance policies, shall develop recommendations for Congress to authorize and fund a uniform minimum data set to be reported electronically by all issuers of long-term care insurance policies under qualified State long-term care insurance partnerships to a secure, centralized electronic query and report-generating mechanism that the State, the Secretary, and other Federal agencies can access."],[0,"(2) Any adjustment or recovery under paragraph (1) may be made only after the death of the individual's surviving spouse, if any, and only at a time—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396p?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1396p. Liens, adjustments and recoveries, and transfers of assets","tname":"The Public Health and Welfare","by":{"0":"i, 4, passim, 25, 25, 2, 4, 24, 25, 25, 25","1":"2, 11"}},{"t":"law","label":"Pub. L. No. 113-67","url":"https://www.govinfo.gov/link/plaw/113/public/67","by":{"0":"12, 13, 25"}},{"t":"law","label":"Pub. L. No. 115-123","url":"https://www.govinfo.gov/link/plaw/115/public/123","by":{"0":"13, 25"}},{"t":"law","label":"Pub. L. No. 98-369","url":"https://www.govinfo.gov/link/statute/98/494","by":{"0":"5"}},{"t":"law","label":"Health Insurance for the Aged Act, Pub. L. No. 89-97","url":"https://www.govinfo.gov/link/statute/79/286","by":{"0":"4"}},{"t":"law","label":"Pub. L. No. 114-10","url":"https://www.govinfo.gov/link/plaw/114/public/10","by":{"0":"13"}},{"t":"law","label":"Pub. L. No. 95-142","url":"https://www.govinfo.gov/link/statute/91/1175","by":{"0":"5, 6","1":"28"}},{"t":"law","label":"Pub. L. No. 103-66","url":"https://www.govinfo.gov/link/statute/107/312","by":{"0":"5","1":"29"}},{"t":"law","label":"Pub. L. No. 113-93","url":"https://www.govinfo.gov/link/plaw/113/public/93","by":{"0":"13"}},{"t":"law","label":"Pub. L. No. 90-248","url":"https://www.govinfo.gov/link/statute/81/821","by":{"0":"4"}},{"t":"reg","label":"42 C.F.R. § 433.136","url":"https://www.ecfr.gov/current/title-42/section-433.136","by":{"0":"27, 39","2":"26"}},{"t":"case","label":"Robert Kruger, Paying a Medicaid Lien after Cricchio v. Pennisi","cite":"69 N.Y. St. B.J. 58","y":1997,"court":"Dec.","url":"https://www.courtlistener.com/c/N.Y.%20St.%20B.J./69/58/","by":{"0":"31"}},{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"sum":"The Court held that the Social Security Administration's interpretations of the statute fell within its lawful interpretative authority.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Barton v. Summers","cite":"293 F.3d 944","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/293/944/","sum":"Explaining that the regulation confirms that “the States are only assignees to the degree that they have paid out for services, and no more”.","sumSrc":"brief:1","by":{"1":"24","2":"49"}},{"t":"case","label":"Bennett v. Kentucky Department of Education","cite":"470 U.S. 656","y":1985,"id":"1984/83-1798","sc":1,"sum":"The Secretary properly determined that Kentucky violated its assurances of compliance with Title I requirements by approving the \"readiness classes\" and thereby misused Title I funds.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"9, 23","2":"49"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"op":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Jackson v. Birmingham Board of Education","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"sum":"The Court held that Title IX allowed suits alleging retaliation for reporting sex discrimination. Such retaliation, the majority reasoned, constituted intentional discrimination on the basis of sex in violation of Title IX. Jackson therefore had the right under Title IX to pursue his claim in court.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"op":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"National Association of Manufacturers v. Department of Defense","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Puerto Rico v. Franklin California Tax-Free Trust","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"1":"25","2":"14"}},{"t":"case","label":"Small v. United States","cite":"544 U.S. 385","y":2005,"id":"2004/03-750","sc":1,"sum":"The Court held that the federal law's phrase, \"convicted in any court,\" encompassed only domestic, not foreign, convictions. The majority reasoned that in determining the scope of the phrase, it was appropriate to assume Congress had domestic concerns in mind. Moreover, the statute's overall language suggested no intent to reach beyond domestic convictions.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Territory of Guam v. United States","cite":"141 S. Ct. 1608","y":2021,"id":"2020/20-382","sc":1,"sum":"A settlement of environmental liabilities must resolve a specific liability under the Comprehensive Environmental Response, Compensation, and Liability Act of 1980 to give rise to a contribution action under that Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Tristani v. Richman","cite":"652 F.3d 360","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/652/360/","sum":"Noting that lower courts have generally reached the same result.","sumSrc":"brief:1","by":{"1":"3, 22","2":"19, 20, 40"}},{"t":"case","label":"United States v. Alvarez-Sanchez","cite":"511 U.S. 350","y":1994,"id":"1993/92-1812","sc":1,"op":1,"sum":"The Court held that the provisions of the federal statute in question do not apply to suspects being held solely on state charges. The Court explained that no delay is said to occur until the suspect is arrested and detained for a federal crime. The six-hour period only begins to expire from the point of a suspect's federal arrest and charging.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(b)"],"stext":{"head":"§1396d. Definitions","paras":[[0,"For purposes of this subchapter—"],[0,"(a) Medical assistance"],[0,"The term \"medical assistance\" means payment of part or all of the cost of the following care and services or the care and services themselves, or both (if provided in or after the third month before the month in which the recipient makes application for assistance or, in the case of medicare cost-sharing with respect to a qualified medicare beneficiary described in subsection (p)(1), if provided after the month in which the individual becomes such a beneficiary) for individuals, and, with respect to physicians' or dentists' services, at the option of the State, to individuals (other than individuals with respect to whom there is being paid, or who are eligible, or would be eligible if they were not in a medical institution, to have paid with respect to them a State supplementary payment and are eligible for medical assistance equal in amount, duration, and scope to the medical assistance made available to individuals described in section 1396a(a)(10)(A) of this title) not receiving aid or assistance under any plan of the State approved under subchapter I, X, XIV, or XVI, or part A of subchapter IV, and with respect to whom supplemental security income benefits are not being paid under subchapter XVI, who are—"],[1,"(i) under the age of 21, or, at the option of the State, under the age of 20, 19, or 18 as the State may choose,"],[1,"(ii) relatives specified in section 606(b)(1) 1 of this title with whom a child is living if such child is (or would, if needy, be) a dependent child under part A of subchapter IV,"],[1,"(iii) 65 years of age or older,"],[1,"(iv) blind, with respect to States eligible to participate in the State plan program established under subchapter XVI,"],[1,"(v) 18 years of age or older and permanently and totally disabled, with respect to States eligible to participate in the State plan program established under subchapter XVI,"],[1,"(vi) persons essential (as described in the second sentence of this subsection) to individuals receiving aid or assistance under State plans approved under subchapter I, X, XIV, or XVI,"],[1,"(vii) blind or disabled as defined in section 1382c of this title, with respect to States not eligible to participate in the State plan program established under subchapter XVI,"],[1,"(viii) pregnant women,"],[1,"(ix) individuals provided extended benefits under section 1396r–6 of this title,"],[1,"(x) individuals described in section 1396a(u)(1) of this title,"],[1,"(xi) individuals described in section 1396a(z)(1) of this title,"],[1,"(xii) employed individuals with a medically improved disability (as defined in subsection (v)),"],[1,"(xiii) individuals described in section 1396a(aa) of this title,"],[1,"(xiv) individuals described in section 1396a(a)(10)(A)(i)(VIII) or 1396a(a)(10)(A)(i)(IX) of this title,"],[1,"(xv) individuals described in section 1396a(a)(10)(A)(ii)(XX) of this title,"],[1,"(xvi) individuals described in section 1396a(ii) of this title, or"],[1,"(xvii) individuals who are eligible for home and community-based services under needs-based criteria established under paragraph (1)(A) of section 1396n(i) of this title, or who are eligible for home and community-based services under paragraph (6) of such section, and who will receive home and community-based services pursuant to a State plan amendment under such subsection,"],[0,"but whose income and resources are insufficient to meet all of such cost—"],[1,"(1) inpatient hospital services (other than services in an institution for mental diseases);"],[1,"(2)(A) outpatient hospital services, (B) consistent with State law permitting such services, rural health clinic services (as defined in subsection (l)(1)) and any other ambulatory services which are offered by a rural health clinic (as defined in subsection (l)(1)) and which are otherwise included in the plan, and (C) Federally-qualified health center services (as defined in subsection (l)(2)) and any other ambulatory services offered by a Federally-qualified health center and which are otherwise included in the plan;"],[1,"(3)(A) other laboratory and X-ray services; and"],[1,"(B) in vitro diagnostic products (as defined in section 809.3(a) of title 21, Code of Federal Regulations) administered during any portion of the emergency period defined in paragraph (1)(B) of section 1320b–5(g) of this title beginning on or after March 18, 2020, for the detection of SARS–CoV–2 or the diagnosis of the virus that causes COVID–19, and the administration of such in vitro diagnostic products;"],[1,"(4)(A) nursing facility services (other than services in an institution for mental diseases) for individuals 21 years of age or older; (B) early and periodic screening, diagnostic, and treatment services (as defined in subsection (r)) for individuals who are eligible under the plan and are under the age of 21; (C) family planning services and supplies furnished (directly or under arrangements with others) to individuals of child-bearing age (including minors who can be considered to be sexually active) who are eligible under the State plan and who desire such services and supplies; and 2 (D) counseling and pharmacotherapy for cessation of tobacco use by pregnant women (as defined in subsection (bb)); and 2 (E) during the period beginning on March 11, 2021, and ending on the last day of the first calendar quarter that begins one year after the last day of the emergency period described in section 1320b–5(g)(1)(B) of this title, a COVID–19 vaccine and administration of the vaccine; and (F) during the period beginning on March 11, 2021, and ending on the last day of the first calendar quarter that begins one year after the last day of the emergency period described in section 1320b–5(g)(1)(B) of this title, testing and treatments for COVID–19, including specialized equipment and therapies (including preventive therapies), and, without regard to the requirements of section 1396a(a)(10)(B) of this title (relating to comparability), in the case of an individual who is diagnosed with or presumed to have COVID–19, during the period such individual has (or is presumed to have) COVID–19, the treatment of a condition that may seriously complicate the treatment of COVID–19, if otherwise covered under the State plan (or waiver of such plan);"],[1,"(5)(A) physicians' services furnished by a physician (as defined in section 1395x(r)(1) of this title), whether furnished in the office, the patient's home, a hospital, or a nursing facility, or elsewhere, and (B) medical and surgical services furnished by a dentist (described in section 1395x(r)(2) of this title) to the extent such services may be performed under State law either by a doctor of medicine or by a doctor of dental surgery or dental medicine and would be described in clause (A) if furnished by a physician (as defined in section 1395x(r)(1) of this title);"],[1,"(6) medical care, or any other type of remedial care recognized under State law, furnished by licensed practitioners within the scope of their practice as defined by State law;"],[1,"(7) home health care services;"],[1,"(8) private duty nursing services;"],[1,"(9) clinic services furnished by or under the direction of a physician, without regard to whether the clinic itself is administered by a physician, including such services furnished outside the clinic by clinic personnel to an eligible individual who does not reside in a permanent dwelling or does not have a fixed home or mailing address;"],[1,"(10) dental services;"],[1,"(11) physical therapy and related services;"],[1,"(12) prescribed drugs, dentures, and prosthetic devices; and eyeglasses prescribed by a physician skilled in diseases of the eye or by an optometrist, whichever the individual may select;"],[1,"(13) other diagnostic, screening, preventive, and rehabilitative services, including—"],[2,"(A) any clinical preventive services that are assigned a grade of A or B by the United States Preventive Services Task Force;"],[2,"(B) with respect to an adult individual, approved vaccines recommended by the Advisory Committee on Immunization Practices (an advisory committee established by the Secretary, acting through the Director of the Centers for Disease Control and Prevention) and their administration; and"],[2,"(C) any medical or remedial services (provided in a facility, a home, or other setting) recommended by a physician or other licensed practitioner of the healing arts within the scope of their practice under State law, for the maximum reduction of physical or mental disability and restoration of an individual to the best possible functional level;"],[1,"(14) inpatient hospital services and nursing facility services for individuals 65 years of age or over in an institution for mental diseases;"],[1,"(15) services in an intermediate care facility for the mentally retarded (other than in an institution for mental diseases) for individuals who are determined, in accordance with section 1396a(a)(31) of this title, to be in need of such care;"],[1,"(16)(A) effective January 1, 1973, inpatient psychiatric hospital services for individuals under age 21, as defined in subsection (h), and, (B) for individuals receiving services described in subparagraph (A), early and periodic screening, diagnostic, and treatment services (as defined in subsection (r)), whether or not such screening, diagnostic, and treatment services are furnished by the provider of the services described in such subparagraph;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396d. Definitions","tname":"The Public Health and Welfare","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1396c","url":"https://www.law.cornell.edu/uscode/text/42/1396c","stext":{"head":"§1396c. Operation of State plans","paras":[[0,"If the Secretary, after reasonable notice and opportunity for hearing to the State agency administering or supervising the administration of the State plan approved under this subchapter, finds—"],[1,"(1) that the plan has been so changed that it no longer complies with the provisions of section 1396a of this title; or"],[1,"(2) that in the administration of the plan there is a failure to comply substantially with any such provision;"],[0,"the Secretary shall notify such State agency that further payments will not be made to the State (or, in his discretion, that payments will be limited to categories under or parts of the State plan not affected by such failure), until the Secretary is satisfied that there will no longer be any such failure to comply. Until he is so satisfied he shall make no further payments to such State (or shall limit payments to categories under or parts of the State plan not affected by such failure)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396c. Operation of State plans","tname":"The Public Health and Welfare","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 1302","url":"https://www.law.cornell.edu/uscode/text/42/1302","by":{"1":"1, 2"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"1":"6"}},{"t":"reg","label":"66 Fed. Reg. 35,437","url":"https://www.govinfo.gov/link/fr/66/35437","by":{"1":"2"}},{"t":"case","label":"Altria Grp., Inc. v. Good","cite":"555 U.S. 70","y":2008,"id":"2008/07-562","sc":1,"sum":"The Court held that the Federal Cigarette Labeling and Advertising Act did not preempt all claims related to \"smoking and health\" under the Maine Unfair Trade Practices Act.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"ar":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Blue Cross Blue Shield v. Cruz","cite":"495 F.3d 510","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/495/510/","by":{"2":"42"}},{"t":"case","label":"Brandon HMA, Inc. v. Bradshaw","cite":"809 So. 2d 611","y":2001,"court":"Miss.","url":"https://www.courtlistener.com/c/So.%202d/809/611/","by":{"2":"44"}},{"t":"case","label":"Bynum v. Magno","cite":"101 P.3d 1149","y":2004,"court":"Haw.","url":"https://www.courtlistener.com/c/P.3d/101/1149/","by":{"2":"44"}},{"t":"case","label":"Cates v. Wilson","cite":"361 S.E.2d 734","y":1987,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/361/734/","by":{"2":"44"}},{"t":"case","label":"Christensen v. Harris Cty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Ellsworth v. Schelbrock","cite":"611 N.W.2d 764","y":2000,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/611/764/","by":{"2":"44"}},{"t":"case","label":"Geier v. Am. Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Haselden v. Davis","cite":"579 S.E.2d 293","y":2003,"court":"S.C.","url":"https://www.courtlistener.com/c/S.E.2d/579/293/","by":{"2":"44"}},{"t":"case","label":"Mem’l Hosp. v. Maricopa Cty.","cite":"415 U.S. 250","y":1974,"id":"1973/72-847","sc":1,"sum":"[his is an' appeal from Cdecision of the Arizona Supreme Court upholding the constitutionality of an Arizona statute requiring a year's residence in a county as a condition to an indigent's receiving nonemergency hospitalization or medical care at the county's expense. 'Held,: The durational residence requirement, in violation of the Equal Protection Clause, creates an \"invidious classification\" that impinges on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"Mut. Pharm. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"N.Y. Dep’t of Soc. Servs. v. Dublino","cite":"413 U.S. 405","y":1973,"id":"1972/72-792","sc":1,"sum":"The 1967 amendments to the Social Security Act included the Federal Work Incentive Program (WIN), designed to help individuals on welfare become wage-earning members of society. The States were required to incorporate this program into their Aid to Families With Dependent Children (AFDC) program, to provide that certain \"employable\" individuals, as a condition for receiving aid, shall register for manpower services, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"24"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Pharm. Rsch. & Mfrs. of Am. v. Walsh","cite":"538 U.S. 644","y":2003,"id":"2002/01-188","sc":1,"sum":"The Court held, 9-0, that the Pharmaceutical Research and Manufacturers of America had not carried its burden of showing a probability of success on the merits of its Commerce Clause claims and, 6-3, that their showing was insufficient to support a finding that the Medicaid Act pre-empts Maine's Rx Program insofar as it threatens to coerce manufacturers into reducing their prices on non- Medicaid sales.","sumSrc":"Oyez","by":{"2":"47, 48"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Rolling Fashion Mart, Inc. v. Mainor","cite":"341 S.E.2d 61","y":1986,"court":"N.C. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/341/61/","by":{"2":"37"}},{"t":"case","label":"U.S. Airways, Inc. v. McCutchen","cite":"569 U.S. 88","y":2013,"id":"2012/11-1285","sc":1,"sum":"The Court held that when a contract is silent on allocation of relief, the parties' intentions are best determined by the common-fund doctrine.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"op":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Wisc. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"2":"32"}},{"t":"reg","label":"42 C.F.R. § 250.31","url":"https://www.ecfr.gov/current/title-42/section-250.31","subs":["(c)"],"by":{"2":"26"}},{"t":"reg","label":"45 C.F.R. § 250.31","url":"https://www.ecfr.gov/current/title-45/section-250.31","subs":["(c)"],"by":{"2":"27"}},{"t":"reg","label":"42 C.F.R. § 433.138","url":"https://www.ecfr.gov/current/title-42/section-433.138","subs":["(b)(1)"],"by":{"2":"19"}},{"t":"reg","label":"42 C.F.R. § 433.139","url":"https://www.ecfr.gov/current/title-42/section-433.139","subs":["(b)","(b)(1)"],"by":{"2":"19, 3"}},{"t":"reg","label":"42 C.F.R. § 433.145","url":"https://www.ecfr.gov/current/title-42/section-433.145","subs":["(a)(1)"],"by":{"2":"49"}},{"t":"reg","label":"42 C.F.R. § 433.146","url":"https://www.ecfr.gov/current/title-42/section-433.146","subs":["(c)"],"by":{"2":"34"}},{"t":"reg","label":"42 C.F.R. § 433.147","url":"https://www.ecfr.gov/current/title-42/section-433.147","subs":["(b)"],"by":{"2":"15"}},{"t":"reg","label":"42 C.F.R. § 433.148","url":"https://www.ecfr.gov/current/title-42/section-433.148","by":{"2":"34"}},{"t":"reg","label":"42 C.F.R. § 450.31","url":"https://www.ecfr.gov/current/title-42/section-450.31","subs":["(c)"],"by":{"2":"27"}},{"t":"reg","label":"34 Fed. Reg. 752","url":"https://www.govinfo.gov/link/fr/34/752","by":{"2":"26"}},{"t":"reg","label":"50 Fed. Reg. 46,652","url":"https://www.govinfo.gov/link/fr/50/46652","by":{"2":"26"}},{"t":"reg","label":"80 Fed. Reg. 31,098","url":"https://www.govinfo.gov/link/fr/80/31098","by":{"2":"3, 39"}},{"t":"reg","label":"85 Fed. Reg. 87,000","url":"https://www.govinfo.gov/link/fr/85/87000","by":{"2":"3, 39"}},{"t":"case","label":"Albertson’s, Inc. v. Brady","cite":"475 So. 2d 986","y":1985,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/475/986/","by":{"3":"10"}},{"t":"case","label":"Joerg v. State Farm Mut. Auto. Ins. Co.","cite":"176 So. 3d 1247","y":2015,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%203d/176/1247/","by":{"3":"17"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"op":10,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"reg","label":"20 C.F.R. § 416.1205","url":"https://www.ecfr.gov/current/title-20/section-416.1205","by":{"3":"22"}},{"t":"reg","label":"42 C.F.R. § 447.50-447","url":"https://www.ecfr.gov/current/title-42/section-447.50-447","by":{"3":"16"}}]};